// Client helpers for the bundled NIH BioArt asset catalogue.
//
// The manifest and SVG files are generated by scripts/sync-bioart.mjs. This
// module keeps the loading and formatting rules in one place so the Figure
// Studio UI, exports and tests all agree on search order, caching and credit
// text. It has no Svelte or Tauri dependencies.

import type { AssetManifest, AssetManifestEntry } from './types';

const MANIFEST_URL = '/bioart/manifest.json';

let manifestRequest: Promise<AssetManifest> | null = null;
const dataUrlRequests = new Map<string, Promise<string>>();

function emptyManifest(): AssetManifest {
  return {
    version: 1,
    generatedAt: new Date().toISOString(),
    source: 'NIH BioArt Source',
    licenseNote: '',
    assets: [],
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function isManifestEntry(value: unknown): value is AssetManifestEntry {
  if (!isRecord(value)) return false;
  return (
    typeof value.id === 'string' &&
    typeof value.title === 'string' &&
    typeof value.category === 'string' &&
    typeof value.file === 'string' &&
    Array.isArray(value.tags)
  );
}

/** Accepts untrusted JSON but only keeps well-formed catalog entries. */
function normalizeManifest(value: unknown): AssetManifest {
  const source = isRecord(value) ? value : {};
  return {
    version: 1,
    generatedAt: typeof source.generatedAt === 'string' ? source.generatedAt : '',
    source: typeof source.source === 'string' ? source.source : 'NIH BioArt Source',
    licenseNote: typeof source.licenseNote === 'string' ? source.licenseNote : '',
    assets: Array.isArray(source.assets) ? source.assets.filter(isManifestEntry) : [],
  };
}

/**
 * Load the generated BioArt manifest once per session. A missing or broken
 * manifest degrades to an empty catalogue rather than breaking Figure Studio.
 */
export function loadAssetManifest(): Promise<AssetManifest> {
  if (!manifestRequest) {
    manifestRequest = fetch(MANIFEST_URL)
      .then((response) => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return response.json() as Promise<unknown>;
      })
      .then(normalizeManifest)
      .catch((error: unknown) => {
        console.warn('[figure] BioArt manifest unavailable:', error);
        return emptyManifest();
      });
  }
  return manifestRequest;
}

/**
 * Case-insensitive search across title, category and tags. Every whitespace
 * separated query term must match. Pass a category (or "All") to narrow the
 * result set.
 */
export function searchAssets(
  manifest: AssetManifest,
  query: string,
  category?: string,
): AssetManifestEntry[] {
  const terms = query
    .trim()
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean);
  const wantedCategory = category?.trim().toLowerCase();

  return manifest.assets.filter((asset) => {
    if (
      wantedCategory &&
      wantedCategory !== 'all' &&
      !splitCategories(asset).some((label) => label.toLowerCase() === wantedCategory)
    ) {
      return false;
    }
    if (terms.length === 0) return true;
    const haystack = [asset.title, asset.category, ...asset.tags]
      .join(' ')
      .toLowerCase();
    return terms.every((term) => haystack.includes(term));
  });
}

/** BioArt stores multi-valued categories as a comma-separated string. */
function splitCategories(asset: AssetManifestEntry): string[] {
  return asset.category
    .split(',')
    .map((label) => label.trim())
    .filter(Boolean);
}

/** "All" followed by the categories present in the manifest, A–Z. */
export function assetCategories(manifest: AssetManifest): string[] {
  const seen = new Map<string, string>();
  for (const asset of manifest.assets) {
    for (const label of splitCategories(asset)) {
      const key = label.toLowerCase();
      if (!seen.has(key)) seen.set(key, label);
    }
  }
  const categories = [...seen.values()].sort((a, b) =>
    a.localeCompare(b, 'en', { sensitivity: 'base' }),
  );
  return ['All', ...categories];
}

export function assetById(
  manifest: AssetManifest,
  id: string,
): AssetManifestEntry | undefined {
  return manifest.assets.find((asset) => asset.id === id);
}

/** Base64 of UTF-8 text without spreading a huge array into the call stack. */
function base64Utf8(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let binary = '';
  const chunkSize = 0x8000;
  for (let offset = 0; offset < bytes.length; offset += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(offset, offset + chunkSize));
  }
  return btoa(binary);
}

/**
 * Fetch a bundled SVG and return it as a data URL, cached by asset id. The
 * result can be embedded in exports that must not depend on relative paths.
 */
export function assetDataUrl(asset: AssetManifestEntry): Promise<string> {
  const cached = dataUrlRequests.get(asset.id);
  if (cached) return cached;

  const request = (async () => {
    const response = await fetch(asset.file);
    if (!response.ok) {
      throw new Error(`Unable to load asset ${asset.id}: HTTP ${response.status}`);
    }
    const svg = await response.text();
    return `data:image/svg+xml;base64,${base64Utf8(svg)}`;
  })();

  dataUrlRequests.set(asset.id, request);
  request.catch(() => dataUrlRequests.delete(asset.id));
  return request;
}

function uniqueAttribution(asset: AssetManifestEntry): string[] {
  const seen = new Set<string>();
  const parts: string[] = [];
  for (const value of [asset.creator, asset.credit]) {
    const text = value?.trim();
    if (!text) continue;
    const key = text.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    parts.push(text);
  }
  return parts;
}

/** One-line credit suitable for a figure caption or an asset inspector. */
export function formatAssetCredit(asset: AssetManifestEntry): string {
  const parts = [asset.title.trim() || asset.id];
  const attribution = uniqueAttribution(asset);
  if (attribution.length) parts.push(`— ${attribution.join(', ')}`);
  const license = asset.license?.trim();
  if (license) parts.push(`(${license})`);
  return parts.join(' ');
}

/**
 * Citation block for the assets actually used in a figure. Entries are
 * deduplicated by id and keep their input order.
 */
export function assetCitationBlock(assets: AssetManifestEntry[]): string {
  const seen = new Set<string>();
  const lines: string[] = [];
  for (const asset of assets) {
    if (!asset || seen.has(asset.id)) continue;
    seen.add(asset.id);
    const citation = asset.citation?.trim();
    lines.push(citation || formatAssetCredit(asset));
  }
  return lines.join('\n');
}
